instrumentation_patch:
diff --git a/crates/graphicle/src/query.rs b/crates/graphicle/src/query.rs
--- a/crates/graphicle/src/query.rs
+++ b/crates/graphicle/src/query.rs
@@ -1803,13 +1803,38 @@
                         "rrf" => rerank_rrf_order(&scores),
                         _ => rerank_order(&scores, mode == "blend"),
                     };
+                    // Evaluation-only instrumentation; not a production setting.
+                    let cutoff = match std::env::var("GRAPHICLE_EVAL_SYMBOL_LINK_CUTOFF") {
+                        Ok(value) => Some(
+                            value
+                                .parse::<f64>()
+                                .ok()
+                                .filter(|v| v.is_finite())
+                                .ok_or_else(|| Error::bad("Evaluation cutoff must be finite"))?,
+                        ),
+                        Err(std::env::VarError::NotPresent) => None,
+                        Err(_) => return Err(Error::bad("Invalid evaluation cutoff")),
+                    };
+                    let scored: Vec<Value> = order
+                        .iter()
+                        .enumerate()
+                        .map(|(rank, &i)| {
+                            json!({"id":linked_memories[i]["memory"]["id"],
+                            "title":linked_memories[i]["title"],"score":scores[i],"rank":rank + 1})
+                        })
+                        .collect();
                     linked_reranker_usage = json!({"model_key":crate::model::key(reranker),
                         "input_tokens":tokens,"candidates":texts.len(),"mode":mode,
-                        "elapsed_ms":started.elapsed().as_secs_f64()*1000.0});
+                        "elapsed_ms":started.elapsed().as_secs_f64()*1000.0,
+                        "cutoff":cutoff,"scored_candidates":scored});
+                    let before = linked_memories.len();
                     linked_memories = order
                         .into_iter()
+                        .filter(|&i| cutoff.is_none_or(|threshold| scores[i] >= threshold))
                         .map(|i| linked_memories[i].clone())
                         .collect();
+                    symbol_links_report["below_cutoff"] = json!(before - linked_memories.len());
+                    symbol_links_report["lifted_memories"] = json!(linked_memories.len());
                     symbol_links_report["reranker"] = linked_reranker_usage.clone();
                 }
                 let omitted = linked_memories
